changeSet.sql:
DO $backfill$ DECLARE v_duplicate_refs bigint; BEGIN SELECT COUNT(*) INTO v_duplicate_refs FROM ( SELECT (entry->>'callLogId')::bigint AS call_log_id FROM n_lead l, jsonb_array_elements(COALESCE(l.call_logs, '[]'::jsonb)) AS entry WHERE entry->>'callLogId' IS NOT NULL AND trim(entry->>'callLogId') <> '' AND (entry->>'callLogId') ~ '^[0-9]+$' GROUP BY (entry->>'callLogId')::bigint HAVING COUNT(DISTINCT l.id) > 1 ) duplicate_refs;
IF v_duplicate_refs > 0 THEN RAISE EXCEPTION 'backfill_n_call_log_lead_from_lead_jsonb failed: % callLogId values are mapped to multiple leads', v_duplicate_refs; END IF;
INSERT INTO n_call_log_lead (call_log_id, lead_id, contact_id) SELECT DISTINCT (entry->>'callLogId')::bigint AS call_log_id, l.id AS lead_id, CASE WHEN entry->>'contactId' IS NOT NULL AND trim(entry->>'contactId') <> '' AND (entry->>'contactId') ~ '^[0-9]+$' THEN (entry->>'contactId')::bigint ELSE NULL END AS contact_id FROM n_lead l, jsonb_array_elements(COALESCE(l.call_logs, '[]'::jsonb)) AS entry WHERE entry->>'callLogId' IS NOT NULL AND trim(entry->>'callLogId') <> '' AND (entry->>'callLogId') ~ '^[0-9]+$' AND EXISTS (SELECT 1 FROM n_call_log c WHERE c.id = (entry->>'callLogId')::bigint) ON CONFLICT (call_log_id) DO NOTHING; END; $backfill$;
